import React, { useState, useEffect } from 'react';

interface SearchResult {
  id: string;
  title: string;
}

export const SearchComponent: React.FC<{ term: string }> = ({ term }) => {
  const [results, setResults] = useState<SearchResult[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const query = term.trim();

    // 1. Handle empty term: clear state and do not fetch
    if (!query) {
      setResults([]);
      setError(null);
      setIsLoading(false);
      return;
    }

    const controller = new AbortController();
    const { signal } = controller;

    const performSearch = async () => {
      setIsLoading(true);
      setError(null);

      try {
        const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, { signal });

        if (!res.ok) {
          throw new Error(`HTTP error: ${res.status} ${res.statusText}`);
        }

        const data: SearchResult[] = await res.json();

        // 2. Guard state update against aborts completed during JSON parsing
        if (!signal.aborted) {
          setResults(data);
        }
      } catch (err: unknown) {
        // Silently exit if request was cancelled/aborted
        if (signal.aborted || (err instanceof DOMException && err.name === 'AbortError')) {
          return;
        }
        setError(err instanceof Error ? err.message : 'An unexpected error occurred');
      } finally {
        if (!signal.aborted) {
          setIsLoading(false);
        }
      }
    };

    performSearch();

    // 3. Cleanup on term change or unmount
    return () => {
      controller.abort();
    };
  }, [term]);

  return (
    <div>
      {isLoading && <p role="status">Loading results...</p>}
      {error && <p role="alert" style={{ color: 'red' }}>{error}</p>}
      {!isLoading && !error && results.length === 0 && term.trim() && (
        <p>No results found.</p>
      )}
      <ul>
        {results.map((item) => (
          <li key={item.id}>{item.title}</li>
        ))}
      </ul>
    </div>
  );
};

---

Why AbortController Alone May Not Prevent Stale State Updates

AbortController.abort() cancels the in-flight network I/O. It does not inherently prevent race conditions in the microtask queue once the response has arrived:

Window between response resolution and parsing: If the network transfer finishes right before the user types the next character, fetch() resolves successfully. If cleanup runs after fetch() resolves but while await res.json() or downstream data processing is pending in the microtask queue, an abort may not cancel non-network JavaScript execution.
Missing checks before `setState`: Unless you explicitly verify !signal.aborted (or track a boolean flag like let isActive = true) before calling state setters, the queued resolution microtasks will execute and call setResults() with stale data from the older, resolved response.

---

UI Behavior While a Request Is Pending
`isLoading === true`: The UI communicates an active search via an inline loader, spinner, or skeleton placeholder.
Result retention: Existing results can remain visible (often dimmed or paired with a subtle loading indicator) to avoid layout shift/flicker while waiting for new results.
Immediate clearing on empty input: If term is cleared, isLoading turns false immediately and results are cleared synchronously without waiting on network cancellation.
Error clearing: Any prior error message is cleared as soon as a new request is dispatched.

